<template><main class="zj-workspace"><ZjPageHeader title="检测报告生成" description="选择项目与资质，登记检测内容，按系统整理现场照片，核对后生成。" /><section class="zj-card"><el-steps :active="step" finish-status="success" align-center><el-step v-for="s in ['选择项目','选择资质','系统与检测内容','照片归类','核对与生成']" :key="s" :title="s"/></el-steps><div style="margin:28px 0" v-loading="busy">
<template v-if="step===0"><el-form label-position="top"><el-form-item label="检测项目（必选）"><el-select v-model="projectId" filterable remote :remote-method="find" @change="choose" placeholder="搜索项目名称"><el-option v-for="p in projects" :key="p.id" :value="p.id" :label="p.projectName+' · '+p.projectNo"/></el-select></el-form-item><template v-if="project"><el-alert :title="project.projectName+' · '+(project.siteAddress||'未填写地址')" :closable="false"/><el-form-item label="报告编号（必填）"><el-input v-model="form.reportNo" maxlength="100"/></el-form-item><el-form-item label="报告日期（必填）"><el-date-picker v-model="form.reportDate" value-format="YYYY-MM-DD"/></el-form-item><div class="zj-grid"><el-form-item v-for="f in [['inspectors','检测人'],['reviewer','审核人'],['approver','批准人']]" :key="f[0]" :label="f[1]"><el-select v-model="staff[f[0]]" :multiple="f[0]==='inspectors'" clearable filterable remote :remote-method="findEmployees" @visible-change="v=>v&&findEmployees('')"><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="e.name+' · '+(e.employeeType||'')+' #'+e.id"/></el-select></el-form-item></div><el-form-item label="编制补充说明"><el-input v-model="form.notes" type="textarea" maxlength="3000"/></el-form-item><el-button @click="editProject">完善项目建筑概况</el-button></template></el-form></template>
<template v-if="step===1"><el-alert title="按选择顺序装入资质原件；请在资质管理中维护公司资料和本次参与人员证书。" :closable="false"/><el-checkbox-group v-model="form.credentialIds"><div v-for="c in credentials" :key="c.id" style="padding:12px;border-bottom:1px solid #eee"><el-checkbox :value="c.id" :disabled="!!c.validUntil&&c.validUntil<form.reportDate">{{c.kind==='company'?'公司':'人员'}} · {{c.title}} · {{c.holder}} · {{c.validUntil||'长期 / 未登记'}}</el-checkbox></div></el-checkbox-group><p v-if="!credentials.length">暂无资质，请先到公司与人员资料栏目上传。</p></template>
<template v-if="step===2"><el-alert title="逐项确认是否存在、是否检测；检测结果与判定需要如实填写，不会自动判定合格。" :closable="false"/><el-button style="margin:12px 0" @click="form.systems.push({name:'',status:'untested',description:'',items:[]})">添加系统</el-button><el-collapse><el-collapse-item v-for="(s,i) in form.systems" :key="i" :name="i" :title="(s.name||'新系统')+' · '+(states[s.status]||'待确认')"><div class="zj-grid"><el-input v-model="s.name" placeholder="系统名称" maxlength="100"/><el-select v-model="s.status"><el-option v-for="(label,key) in states" :key="key" :value="key" :label="label"/></el-select></div><el-input style="margin:12px 0" v-model="s.description" type="textarea" :rows="3" maxlength="10000" placeholder="系统设置及检测说明，例如设备数量、设置位置、未检测原因"/><el-table :data="s.items"><el-table-column label="设备 / 检验项目" min-width="150"><template #default="{row}"><el-input v-model="row.name" maxlength="200"/></template></el-table-column><el-table-column label="状态" width="165"><template #default="{row}"><el-select v-model="row.status" @change="row.verdict='pending'"><el-option v-for="(label,key) in states" :key="key" :value="key" :label="label"/></el-select></template></el-table-column><el-table-column v-for="f in [['requirement','标准要求'],['location','检测部位'],['result','检验结果']]" :key="f[0]" :label="f[1]" min-width="150"><template #default="{row}"><el-input v-model="row[f[0]]" type="textarea" maxlength="2000"/></template></el-table-column><el-table-column label="判定" width="115"><template #default="{row}"><el-select v-model="row.verdict"><el-option v-for="(label,key) in verdicts" :key="key" :value="key" :label="label" :disabled="row.status!=='tested'&&['pass','fail'].includes(key)"/></el-select></template></el-table-column><el-table-column width="65"><template #default="{row}"><el-button link type="danger" @click="s.items.splice(s.items.indexOf(row),1)">移除</el-button></template></el-table-column></el-table><el-button @click="s.items.push({name:'',status:'untested',requirement:'',location:'',result:'',verdict:'pending'})">添加设备 / 检验项目</el-button><el-button type="danger" link @click="removeSystem(i)">移除此系统</el-button></el-collapse-item></el-collapse></template>
<template v-if="step===3"><el-alert title="批量上传后手动归类。每系统每页最多四张照片；日期请按实际拍摄日期填写。" :closable="false"/><FileUpload v-model="uploads" :limit="200" :file-type="['jpg','jpeg','png']" :file-size="15"/><div style="display:flex;gap:12px;margin:16px 0"><el-select v-model="batchSystem" placeholder="统一归类到系统"><el-option v-for="s in tested" :key="s.name" :value="s.name" :label="s.name"/></el-select><el-date-picker v-model="batchDate" value-format="YYYY-MM-DD" placeholder="统一拍摄日期"/><el-button @click="batch">应用到未填写照片</el-button></div><el-table :data="form.photos"><el-table-column label="照片" width="120"><template #default="{row}"><el-image :src="fileUrl(row.url)" style="width:90px;height:70px" fit="contain" :preview-src-list="[fileUrl(row.url)]" preview-teleported/></template></el-table-column><el-table-column label="所属系统（必填）"><template #default="{row}"><el-select v-model="row.system"><el-option v-for="s in tested" :key="s.name" :value="s.name" :label="s.name"/></el-select></template></el-table-column><el-table-column label="照片说明"><template #default="{row}"><el-input v-model="row.caption" maxlength="80"/></template></el-table-column><el-table-column label="拍摄日期（必填）"><template #default="{row}"><el-date-picker v-model="row.date" value-format="YYYY-MM-DD"/></template></el-table-column></el-table></template>
<template v-if="step===4"><el-descriptions :column="2" border><el-descriptions-item label="项目">{{project?.projectName}}</el-descriptions-item><el-descriptions-item label="报告编号">{{form.reportNo}}</el-descriptions-item><el-descriptions-item label="资质">{{form.credentialIds.length}} 项</el-descriptions-item><el-descriptions-item label="照片">{{form.photos.length}} 张</el-descriptions-item></el-descriptions><el-table :data="form.systems"><el-table-column prop="name" label="系统"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="设备 / 检验项目数"><template #default="{row}">{{row.items.length}}</template></el-table-column><el-table-column label="照片数"><template #default="{row}">{{form.photos.filter(p=>p.system===row.name).length}}</template></el-table-column></el-table><el-alert title="请预览核对。未检测、未判定内容不会自动标记合格；生成后仍须完成签字盖章。" type="warning" :closable="false"/><el-button :disabled="busy" @click="preview">预览 PDF</el-button><el-button type="primary" :disabled="busy" @click="generate">生成并归档</el-button><h3>本项目历史报告</h3><el-table :data="history"><el-table-column prop="reportNo" label="报告编号"/><el-table-column prop="createdAt" label="生成时间"/><el-table-column label="文件"><template #default="{row}"><el-button link @click="show(row.file)">预览 / 打印</el-button></template></el-table-column></el-table></template>
</div><div style="display:flex;justify-content:space-between"><el-button :disabled="step===0||busy" @click="step--">上一步</el-button><el-button v-if="step<4" type="primary" :disabled="busy" @click="next">下一步</el-button></div></section><PdfPreview v-model="previewOpen" :url="previewUrl" title="检测报告预览"/></main></template>
<script setup>
import ZjPageHeader from '@/components/Zj/PageHeader.vue'
import '@/assets/styles/zhongji.scss'
import FileUpload from '@/components/FileUpload/index.vue'
import PdfPreview from '../wbcard/components/PdfPreview.vue'
import { useReportWizard } from './composables/useReportWizard'

const {
  staff, employees, step, busy, projects, projectId, project, credentials, history, uploads, batchSystem, batchDate,
  previewOpen, previewUrl, states, verdicts, form, tested, fileUrl, findEmployees, find, choose, editProject,
  batch, removeSystem, next, show, preview, generate
} = useReportWizard()
</script>

<style scoped>.zj-workspace :deep(.el-form .el-select),.zj-workspace :deep(.el-form .el-date-editor){width:100%}.zj-grid>.el-select{width:100%}.zj-card>.el-steps{padding:8px 0}.zj-workspace :deep(.el-collapse-item__content){padding-top:16px}</style>
